const $=id=>document.getElementById(id), role=document.body.dataset.role, app=$('app'), work=$('work'), body=$('workbody');let s=fresh(), lens=0, template=0, light="dark", page=0, studioView='slides', message='';
// One local project per browser origin; portable JSON remains the backup.
let storageNotice='';
try{const raw=sessionStorage.getItem('briefcase-handoff');if(raw){s=validate(JSON.parse(raw));sessionStorage.removeItem('briefcase-handoff');try{persist(localStorage,s)}catch{storageNotice='Local save unavailable. Export JSON to keep your project.'}}else{s=restore(localStorage)||s}}catch{storageNotice='Saved project could not be restored. Open a JSON backup or start a new project.'}
function saveLocal(){try{persist(localStorage,s);storageNotice='Saved on this browser';return true}catch{storageNotice='Local save unavailable. Export JSON to keep your project.';return false}finally{const el=$('local-save-status');if(el)el.textContent=storageNotice}}
function handoff(){if(saveLocal()){try{sessionStorage.removeItem('briefcase-handoff')}catch{}return}sessionStorage.setItem('briefcase-handoff',JSON.stringify(s))}
const esc=x=>String(x).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const t=()=>templates[s.t], target=()=>s.t===2?s.method:t().target, current=()=>s.t===2?s.currentMethod:t().current;const gapCount=()=>gaps(s).filter(g=>g.missing).length;const link=(i,text)=>`<a class="button perspective-action" data-go="${i}" href="/briefcase/${roles[i][2]}/"><span>${text||roles[i][1]}</span><span aria-hidden="true">↗</span></a>`;const action=(id,text,primary=false)=>`<button data-action="${id}" class="${primary?'primary':''}">${text}</button>`;
const strip=()=>`<div class="strip" aria-label="Executive perspectives">${roles.map((r,i)=>role==='home'?`<button data-lens="${i}" class="${lens===i?'active':''}"><strong>${r[0]}</strong>${r[3]}</button>`:`<a data-go="${i}" href="/briefcase/${r[2]}/" class="${+role===i?'active':''}"><strong>${r[0]}</strong>${r[3]}</a>`).join('')}</div>`;
const descriptions=['Establish the strategic mandate and review outstanding decisions.','Assess the investment and its sensitivity to adoption and cost.','Compose a deliverable architecture and identify dependencies.','Challenge the proposed design and prepare a security investment request.','Review unresolved exposure and assign accountable risk ownership.'];
function investmentCards(){const cards=[['Establish the baseline','Measure current authentication, credential and support expenditure.','M3 19V12 M8 19V9 M13 19V13 M18 19V5 M2 9l6-5 5 4 8-7'],['Fund the transformation','Budget integration, credentials, enrolment, training and recovery.','M3 6h16v14H3z M3 6V3h14v3 M19 10h3v6h-7v-6z'],['Realise business value','Track actual adoption, avoidable costs and productivity gains separately.','M3 18l7-7 4 4 7-9 M14 6h7v7'],['Protect the investment','Assess the financial consequences of delays and unsuccessful adoption.','M12 3L22 21H2z M12 9v5 M12 17v1']];return cards.map(([title,desc,path],i)=>`<div class="priority-item investment-card"><svg viewBox="0 0 24 24" width="28" height="28" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" class="${i===3?'amber':'mint'}"><path d="${path}"/></svg><h3>${title}</h3><p>${desc}</p></div>`).join('')}
function chart(f){const max=Math.max(1,...f.rows.flatMap(r=>[r.current,r.proposed])), x=m=>48+550*m/(f.rows.length-1), y=v=>200-170*v/max;const path=k=>f.rows.map((r,i)=>`${i?'L':'M'}${x(r.month).toFixed(2)} ${y(r[k]).toFixed(2)}`).join(' ');return `<svg class="chart" viewBox="0 0 620 230" role="img" aria-label="Cumulative current and proposed expenditure"><g stroke="#345044" stroke-dasharray="4 5">${[0,.5,1].map(v=>`<path d="M48 ${y(max*v)} H598"/>`).join('')}</g><g fill="#a6b9ae" font-size="11"><text x="3" y="33">${(max/1e6).toFixed(2)}m</text><text x="20" y="204">0</text><text x="48" y="222">Now</text><text x="555" y="222">${s.finance.years} years</text></g><path d="${path('current')}" fill="none" stroke="#a6b9ae" stroke-width="2.5"/><path d="${path('proposed')}" fill="none" stroke="#79e5ad" stroke-width="3"/></svg><div class="small">● Current expenditure &nbsp; <span class="mint">● Proposed expenditure</span></div>`}
function riskView(gs){const rows=riskRows(s,gs),r=s.risk||emptyRisk();return `<section class="panel"><div class="eyebrow">Chief Risk Officer · Governance</div><h2>Residual exposure</h2><div id="risk-top">${riskSummary()}</div><details><summary>Risk register</summary><p>Risk appetite: <strong>${esc(r.appetite)}</strong> · ${rows.some(v=>v.status==='Not assessed')?'Assessment incomplete':rows.filter(v=>v.status==='Above appetite').length+' above appetite'}</p>${rows.map(v=>`<div class="gap"><h3>${esc(v.title)}</h3><div class="rowline">Inherent → residual <strong>${esc(v.inherent)} → ${esc(v.residual)}</strong></div><div class="rowline">Treatment <strong>${esc(v.treatment)}</strong></div><p>${esc(v.status)}</p><small>Owner: ${esc(v.owner||'Unassigned')} · Evidence: ${esc(v.evidence||'Not supplied')}</small></div>`).join('')}</details></section><section class="panel"><div class="eyebrow">Risk governance</div><h2>${esc(s.decision)}</h2><p>Accountable owner: ${esc(s.owner||'Unassigned')}</p><p>Ratings are user-entered qualitative judgments, not calculated probabilities. Within appetite is not approval. Validate evidence and obtain authorised acceptance outside this workspace.</p>${link(3,'Review security findings')} ${link(2,'Review architecture')}</section>`}
function riskFields(){const r=s.risk||emptyRisk();const opts=(values,v)=>values.map(x=>`<option ${x===v?'selected':''}>${x}</option>`).join('');return `<h2>Risk assessment</h2><div class="control"><label>Maximum tolerated residual rating<select data-appetite="1">${opts(ratings,r.appetite)}</select></label></div>${gaps(s).map(g=>{const v=r.records[g.id]||emptyRecord();return `<details class="risk-edit"><summary>${esc(g.title)} · ${esc(v.residual)}</summary><fieldset>${[['inherent','Inherent rating',ratings],['residual','Residual rating',ratings],['treatment','Treatment',treatments]].map(([k,l,a])=>`<div class="control"><label>${l}<select data-risk="${g.id}" data-key="${k}">${opts(a,v[k])}</select></label></div>`).join('')}${[['owner','Risk owner'],['evidence','Evidence reference (not verified)'],['rationale','Assessment rationale']].map(([k,l])=>`<div class="control"><label>${l}<input maxlength="2000" data-risk="${g.id}" data-key="${k}" value="${esc(v[k])}"></label></div>`).join('')}</fieldset></details>`}).join('')}`}
function deliver(){return `<section id="decision-brief" class="panel delivery"><div class="eyebrow">${role==='home'?'04 / Consolidate the decision':'Next step'}</div><h2>Your executive brief</h2><p>Nine slides based on your current initiative, assumptions and assessments.</p><div class="completion-list">${roles.map((r,i)=>`<a data-go="${i}" href="/briefcase/${r[2]}/"><span>${r[0]} · ${r[1]}</span><small>${reviewStatus(i)}</small></a>`).join('')}</div><p class="small">Outstanding assessments and reassessments remain visible in the brief. Review is not formal approval.</p><div class="eyebrow">05 / Generate the executive brief</div>${action('studio-open','Prepare executive brief',true)}</section>`}
function showStudio(){const m=deck(s,template,light);page=Math.max(0,Math.min(page,m.slides.length-1));open(`<h2>Executive brief</h2><p class="small">Nine slides · Generated from your current project · ${[0,1,2,3,4].filter(i=>status(s,i)==='Reviewed').length}/5 reviews current</p><nav class="studio-tabs" aria-label="Brief formats">${[['slides','Presentation'],['text','Decision brief'],['raw','Raw JSON'],['api','API reference']].map(([id,label])=>`<button data-action="view-${id}" aria-pressed="${studioView===id}">${label}</button>`).join('')}</nav>${studioView==='slides'?`<div class="studio-preview">${preview(m,page)}</div><div class="studio-pager">${action('prev','Previous')}<span>${page+1} / ${m.slides.length}</span>${action('next','Next')}</div>`:studioView==='text'?`<section class="studio-text"><div class="eyebrow">Decision narrative / Plain text</div><h3>${esc(m.title)}</h3>${brief().split('\n\n').map(v=>`<p>${esc(v)}</p>`).join('')}${action('text','Download text')}</section>`:studioView==='raw'?`<section class="studio-text"><div class="eyebrow">Portable intelligence / JSON</div><p>Project data is reusable; the presentation model contains the selected audience and theme.</p><details open><summary>Canonical project</summary><pre tabindex="0">${esc(JSON.stringify(pack(s),null,2))}</pre>${action('portable','Download project JSON')}</details><details><summary>Generated presentation model</summary><pre tabindex="0">${esc(JSON.stringify(m,null,2))}</pre>${action('model','Download presentation JSON')}</details></section>`:`<section class="studio-text"><div class="eyebrow">Integration / Generation contract</div><h3>Generate from portable intelligence.</h3><p>Local JavaScript modules and terminal commands. No hosted REST API or credentials required.</p><pre>node scripts/briefcase.mjs validate project.json
node scripts/briefcase.mjs compose project.json &gt; presentation.json
node scripts/briefcase.mjs html project.json &gt; brief.html</pre><p><a href="/briefcase/api.html" target="_blank" rel="noopener">Read generation guide ↗</a> · <a href="/briefcase/api.txt" target="_blank" rel="noopener">Raw text ↗</a></p></section>`}<div class="control"><label for="brief-audience">Audience</label><select id="brief-audience">${layouts.map((l,i)=>`<option value="${i}" ${template===i?'selected':''}>${esc(l[0])}</option>`).join('')}</select></div><div class="control"><label for="brief-theme">Theme</label><select id="brief-theme"><option value="dark" ${light==='dark'?'selected':''}>Edwardcher</option><option value="light" ${light==='light'?'selected':''}>Corporate light</option><option value="blue" ${light==='blue'?'selected':''}>Corporate blue</option></select></div><div class="actions">${action('pptx','Download PowerPoint (.pptx)',true)}${action('pdf','Print / Save as PDF')}</div><details><summary>Other export formats</summary><div class="actions">${action('deck','Download HTML')}${action('model','Download JSON model')}</div></details><p class="small">PDF uses browser printing. Embedded browsers may require a full browser.</p><div id="export-status" role="status"></div>`)}
document.addEventListener('change',e=>{if(e.target.id==='brief-audience'){template=Number(e.target.value);page=0;showStudio()}if(e.target.id==='brief-theme'){light=e.target.value;showStudio()}});
async function ppt(){const status=$('export-status');try{status.textContent='Preparing PowerPoint…';if(!globalThis.PptxGenJS)await new Promise((ok,no)=>{const a=document.createElement('script');a.src='/briefcase/vendor/pptxgen.bundle.js';a.onload=ok;a.onerror=no;document.head.append(a)});const p=await powerpoint(deck(s,template,light),globalThis.PptxGenJS);await p.writeFile({fileName:'edwardcher-decision-brief.pptx'});status.textContent='Generated. Check downloads.'}catch(e){status.textContent='Export failed. Try a full browser.'}}
const dossierStory=[
 {hook:'Make passwords the exception.',short:'Reduce reusable secrets and sign-in friction.',value:['Reduce credential exposure','Simplify sign-in','Retire avoidable OTP costs'],measure:'Track eligible application coverage and password retirement.',icon:'<rect x="13" y="23" width="35" height="28" rx="5"/><path d="M21 23v-8a10 10 0 0 1 20 0v8M30 34v7M49 13l5 5 10-12"/>'},
 {hook:'One credential experience. Separate trust domains.',short:'Connect access across doors, devices and applications.',value:['Simplify credential issuance','Coordinate access revocation','Reduce duplicate support'],measure:'Track revocation latency across physical and digital systems.',icon:'<rect x="4" y="10" width="27" height="42" rx="3"/><path d="M24 32h2M36 20h25v22H36zM32 48h33M31 30h5"/>'},
 {hook:'Raise assurance without disrupting access.',short:'Modernise factors and manage remaining password risk.',value:['Improve factor assurance','Reduce avoidable friction','Manage fallback exposure'],measure:'Track method coverage, exceptions and sign-in disruption.',icon:'<path d="M32 5l23 9v16c0 14-13 23-23 29C22 53 9 44 9 30V14zM21 31l8 8 15-17"/>'}
];
dossierStory.push({hook:'Authorise the transaction.',short:'Assess strong customer authentication and dynamic linking.',value:['Bind amount and payee','Reduce avoidable OTP costs','Strengthen payment authorisation'],measure:'Validate applicable PSD2 requirements and transaction binding.',icon:'<path d="M8 18L34 5l26 13H8zM14 22v28M28 22v28M42 22v28M56 22v28M8 54h52"/>'});
const benefitNotes=[
['Reduce reliance on reusable passwords and exposure to phishing and credential theft. Recovery and sessions still require protection.','Reduce password entry and reset friction where applications and authenticators support the target journey.','Avoid SMS OTP delivery costs where transactions are displaced; savings depend on actual usage and adoption.'],
['Reduce separate issuance workflows by using compatible credentials across physical and digital access.','Coordinate removal of access across systems; validate offline reader delays and independent trust policies.','Reduce duplicate credential administration and support where redundant processes can actually be retired.'],
['Choose factors appropriate to the threat model; OTP and ordinary push are not inherently phishing-resistant.','Reduce unnecessary prompts and support friction through appropriate factor selection and policy.','Protect fallback and recovery against assurance downgrade; validate remaining password exposure.']];
benefitNotes.push(['Verify amount and payee binding.','Model actual OTP displacement.','Validate factor independence and approval integrity.']);
const dossierIcon=i=>`<svg viewBox="0 0 68 64" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round">${dossierStory[i].icon}</svg>`;
function initiativeProgress(i){const active=s.t===i, reviewed=roles.map((_,j)=>active&&status(s,j)==='Reviewed'), count=reviewed.filter(Boolean).length;return `<div class="initiative-progress">${active?`<span class="initiative-progress-label">Executive reviews <span>${count}/5</span></span>`:''}<span class="initiative-progress-track" aria-hidden="true">${reviewed.map(done=>`<span class="${done?'reviewed':''}"></span>`).join('')}</span></div>`}
function narrativeEditor(){const n=narrative(s);return `<details class="inline-editor"><summary>Refine opportunity narrative</summary>${Object.entries(n).map(([k,v])=>`<label class="journey-field">${k==='headline'?'Headline':k==='problem'?'Business problem':'Proposed transformation'}<textarea data-opportunity="${k}" maxlength="${k==='headline'?100:400}" rows="${k==='headline'?2:4}">${esc(v)}</textarea></label>`).join('')}<button data-action="save-opportunity" class="primary">Save narrative</button></details>`}
function opportunity(f,count){const d=dossierStory[s.t], max=Math.max(1,f.decision.baseline,f.decision.now,f.decision.later), delta=f.decision.coi, positive=delta>=0;return `<div class="templates dossier-choices">${templates.map((v,i)=>`<button data-template="${i}" aria-pressed="${s.t===i}" class="${s.t===i?'active':''}"><div class="dossier-card-top">${dossierIcon(i)}<span class="small">0${i+1} ${s.t===i?' / SELECTED':''}</span></div><h2>${esc(v.name)}</h2><span>${dossierStory[i].short}</span>${initiativeProgress(i)}</button>`).join('')}</div>${compactContext()}<section class="panel opportunity dossier-opportunity"><div class="eyebrow">02 / Understand the opportunity</div><div class="dossier-story"><div><h2>${esc(narrative(s).headline)}</h2><p>${esc(narrative(s).problem)}</p><p>${esc(narrative(s).transformation)}</p>${narrativeEditor()}<h3>Expected benefits</h3><div class="outcome-list">${d.value.map((v,i)=>`<details class="benefit-tip"><summary><b aria-hidden="true">↗</b> ${esc(v)} <small aria-hidden="true">ⓘ</small></summary><p>${esc(benefitNotes[s.t][i])}</p></details>`).join('')}</div></div><div class="dossier-art">${dossierIcon(s.t)}</div></div>${initiativeArt(s.t,current(),target())}<div class="dossier-economics"><div><div class="eyebrow">${s.finance.years}-year business case</div><div class="hero-number ${positive?'':'amber'}">${money(Math.abs(delta))}</div><p>${positive?'Modelled net savings':'Modelled additional cost'} · undiscounted</p><div class="dossier-bars">${[['Retain existing approach',f.decision.baseline],['Proceed as planned',f.decision.now],['Defer '+context(s).deferral+' months',f.decision.later]].map(([label,n],i)=>`<div><span>${label}</span><strong>${money(n)}</strong><div class="bar-track"><div class="bar-fill ${i===2?'deferred':i?'proposed':''}" style="width:${100*n/max}%"></div></div></div>`).join('')}</div></div><div class="dossier-readiness"><small>Investment payback</small><strong>${f.payback===null?'Not reached':f.payback.toFixed(1)+' months'}</strong><small>Open design gaps</small><strong class="${count?'amber':''}">${count} / ${gaps(s).length}</strong><p>${d.measure}</p><small>Implementation investment</small><strong>${money(f.decision.investment)}</strong><small>Additional cost of deferral</small><strong>${money(f.decision.deferralCost)}</strong></div></div>${programmeSummary()}<div class="dossier-bottom"><small>Illustrative planning assumptions · outcomes require validation.</small>${inlineEditor('Edit initiative assumptions',controls()+`<div class="journey-fields">${fields.map(v=>finInput(v[0])).join('')}</div>`)}</div></section>`}
const questions=['Is this worth pursuing?','Can we justify the investment?','Can we deliver it successfully?','What exposure must we address?','Is the remaining risk acceptable?'];
const outputs=['strategic mandate','investment case','delivery blueprint','security treatment plan','risk recommendation'];
function progress(){return `<div class="journey-progress" id="journey-progress">${roles.map((r,i)=>`<a data-go="${i}" href="/briefcase/${r[2]}/" class="${role==i?'active':''}"><b>${r[0]} · ${r[3]}</b><small>${status(s,i)==='Draft'?'Not reviewed':status(s,i)}</small></a>`).join('')}</div>`}
const monetary=k=>['unit','caseCost','fixed','investment','recurring'].includes(k);
const currencyField=(k,input)=>monetary(k)?`<span class="currency-field"><span aria-hidden="true">USD</span>${input}</span>`:input;
function finInput(k){if(k==='investment'&&context(s).itemized)return `<p class="small">Migration estimate is controlled by the itemized investment breakdown.</p>`;const [_,l,v,min,max,step,help]=fields.find(x=>x[0]===k);return `<label class="journey-field">${l}${currencyField(k,`<input aria-label="${l}${monetary(k)?' (USD)':''}" type="number" data-fin="${k}" min="${min}" max="${max}" step="${step}" value="${s.finance[k]}">`)}</label>`}
function controls(){return select('context','Population',s.t===1?['Workforce']:['Customer','Workforce'])+(s.t===2?select('currentMethod','Current MFA',methods)+select('method','Proposed MFA',methods):'')+select('recovery','Recovery mechanism',['SMS only','Alternative registered credential','Assisted re-proofing'])+check('proofing','Specify enrolment identity verification')+check(s.t===1?'separation':'session',s.t===1?'Specify independent trust domains':'Specify session protection')}
function roadmap(){const n=s.finance.ramp, m=milestones(n);return `<section class="panel initiative-roadmap"><div class="eyebrow">Delivery planning</div><h2>Transformation roadmap <span class="mint">· ${n} months</span></h2><div class="roadmap-visual roadmap-milestones">${m.map((v,i)=>`<div style="--step:${i}"><span class="road-icon" aria-hidden="true">${['◎','◇','↗','✓'][i]}</span><b>${v.label}</b><strong>Month ${v.month}</strong>${i?`<p>${esc(guidance[s.t].stages[i-1])}</p>`:'<p>Confirm scope, baseline and ownership.</p>'}</div>`).join('')}</div><p class="small">Illustrative milestones · delivery feasibility requires validation.</p>${inlineEditor('Rollout duration',finInput('ramp'))}</section>`}
function timeline(){const n=s.finance.ramp,h=s.finance.years*12,span=Math.max(n,h,1),ends=milestones(n).map(v=>v.month);return `<div class="hero-number">${n} months</div><p>Planned rollout · ${h} month evaluation horizon</p><div class="gantt">${['Discovery & pilot','Scale deployment','Enforce & stabilise'].map((l,i)=>`<div><strong>${l}</strong><div class="gantt-track"><span style="left:${100*ends[i]/span}%;width:${100*(ends[i+1]-ends[i])/span}%"></span></div><small>Month ${ends[i]}–${ends[i+1]}</small></div>`).join('')}</div><p class="small">Illustrative milestone allocation: pilot ${ends[1]}, scale ${ends[2]}, full rollout ${n}. ${n>h?'Rollout exceeds evaluation horizon.':''} Financial savings ramp linearly; validate actual dependencies.</p>`}
function riskSummary(){const rr=riskRows(s,gaps(s)),r=s.risk||emptyRisk(),a=rr.filter(x=>x.status==='Not assessed').length,b=rr.filter(x=>x.status==='Above appetite').length;return `<div class="risk-metrics">${[[b,'Above appetite'],[a,'Unassessed'],[rr.filter(x=>x.owner.trim()).length+'/'+rr.length,'Owners assigned']].map(([v,l])=>`<div><strong>${v}</strong><small>${l}</small></div>`).join('')}</div><p>${a?'Risk position cannot yet be determined.':'Residual ratings compared with stated appetite.'}</p><h3>Exposure profile</h3>${exposureSVG(rr,r.appetite)}<p class="small">Use Edit to assess exposure and treatment.</p>`}
const reviewLabels=['Strategic assumptions','Financial assumptions','Architecture and delivery','Security treatments','Risk appetite and assessment'];
const reviewText=['Record the strategic mandate.','Record the investment case.','Record the delivery blueprint.','Record the security treatment plan.','Record the risk recommendation.'];
const reviewStatus=i=>({Draft:'Not reviewed',Reassess:'Requires reassessment',Reviewed:'Review recorded'}[status(s,i)]||status(s,i));
function inlineEditor(title,fields){return `<details class="inline-editor"><summary><span>${title}</span><span class="mint">✎ Edit</span></summary><div class="inline-fields">${fields}<button type="button" data-action="apply-inline" class="primary">Apply & refresh</button></div></details>`}
function securityField(id){return id==='REC'?select('recovery','Recovery mechanism',['SMS only','Alternative registered credential','Assisted re-proofing']):id==='ENR'?check('proofing','Specify enrolment identity verification'):check(s.t===1?'separation':'session',s.t===1?'Specify independent trust domains':'Specify session protection')}
function assumptionSummary(){const i=+role;return i===0?inlineEditor('Investment and rollout assumptions',finInput('investment')+finInput('ramp')):i===1?inlineEditor('Financial assumptions',`<div class="journey-fields">${fields.map(v=>finInput(v[0])).join('')}</div>`):i===2?inlineEditor('Architecture and delivery assumptions',controls()+finInput('ramp')):i===4?inlineEditor('Assess risks and set appetite',riskFields()):''}
function conclusion(){const i=+role;return `<section class="panel conclusion-panel"><div class="eyebrow">02 / Conclude</div><h2>${questions[i]}</h2><p>${reviewText[i]}</p>${i===0?select('decision','Working recommendation',['Pending review','Recommend funding','Recommend deferral','Escalate for review']):i===4?`<div class="control"><label>Accountable risk owner<input data-state="owner" value="${esc(s.owner)}"></label></div>`:''}${(s.referrals||[]).filter(v=>v.to===i&&v.pending).map(v=>`<p class="small"><strong>Review requested by ${roles[v.from][0]}:</strong> ${esc(v.reason)}</p>`).join('')}<p id="review-state" class="small">${reviewStatus(i)} · Working review, not formal approval.</p><div class="review-navigation"><div class="referral-actions"><label for="referral-target" class="referral-label">Refer for review</label><div class="referral-control"><select id="referral-target" aria-label="Receiving executive">${roles.map((r,j)=>j===i?'':`<option value="${j}" ${j===[1,0,1,2,0][i]?'selected':''}>${r[0]}</option>`).join('')}</select>${action('refer','Refer to '+roles[[1,0,1,2,0][i]][0]+' ↗')}</div></div>${action('commit',i===4?'Complete & generate brief →':'Save & next: '+roles[i+1][0]+' →',true)}</div></section>`}

function impactSummary(){const f=financial(s);return `<div class="kpis"><div><small>Revised net benefit</small><strong>${money(f.net)}</strong></div><div><small>Treatments selected</small><strong>${gaps(s).filter(g=>g.selected).length}</strong></div></div><p class="small">CFO and CIO must reassess affected assumptions. Selected treatments do not close design gaps.</p>`}
const roleIcons=['M12 3l9 9-9 9-9-9z M12 8v8 M8 12h8','M3 6h18v14H3z M3 6V3h15v3 M16 11h5v5h-5z','M12 3v5 M5 16v-5h14v5 M9 3h6v5H9z M2 16h6v5H2z M16 16h6v5h-6z','M12 2l9 4v6c0 5-5 9-9 10-4-1-9-5-9-10V6z M8 12l3 3 5-6','M12 3v18 M5 21h14 M3 7h18 M6 7l-4 8h8z M18 7l-4 8h8z'];
function roleIcon(i){return `<svg viewBox="0 0 24 24" width="26" height="26" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linejoin="round" stroke-linecap="round" aria-hidden="true"><path d="${roleIcons[i]}"/></svg>`}
function perspectives(){return `<section class="decision-perspectives"><div class="eyebrow">03 / Explore the decision</div><h2>From strategic intent to informed decisions.</h2><p>Evaluate the transformation from each executive perspective. Align strategy, investment, architecture, security and risk before committing to a decision.</p><details class="perspectives-context"><summary><svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" aria-hidden="true"><circle cx="12" cy="12" r="9"/><path d="M12 11v5M12 7.5h.01"/></svg><span>About these perspectives</span><svg class="context-chevron" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="m6 9 6 6 6-6"/></svg></summary><div class="perspectives-context-copy"><p>The Briefcase serves as an interactive reference for exploring executive decision-making. Roles, responsibilities and reporting lines vary by organization. These five perspectives represent complementary areas of accountability, not a prescribed hierarchy.</p></div></details><div class="perspective-cards">${roles.map((r,i)=>`<a data-go="${i}" href="/briefcase/${r[2]}/"><span class="mint">${roleIcon(i)} ${r[0]} · ${r[3]}</span><strong>${r[1]}</strong><span>${questions[i]}</span><small class="perspective-arrow"><span aria-hidden="true">↗</span></small></a>`).join('')}</div></section>`}
function workspaceNav(){return `<nav class="workspace-nav" aria-label="Briefcase workspace"><a data-home href="/briefcase/" ${role==='home'?'aria-current="page"':''}>Dossier</a>${roles.map((r,i)=>`<a data-go="${i}" href="/briefcase/${r[2]}/" ${role==i?'aria-current="page"':''}>${r[0]}${role==='home'?'':`<small>${reviewStatus(i)}</small>`}</a>`).join('')}</nav>`}
function helloEditor(){if(s.t!==2)return '';const a=s.helloFinance||{investment:0,recurring:0,displace:0,supportReduction:0};return `<details class="inline-editor"><summary>Windows Hello for Business alternative</summary><p class="small">Optional alternative using the same baseline and rollout. Enter incremental costs and displacement; no assumed entitlement or biometric superiority.</p><div class="journey-fields">${Object.entries({investment:'Implementation (USD)',recurring:'Annual additional cost (USD)',displace:'SMS displacement (%)',supportReduction:'Support reduction (%)'}).map(([k,l])=>`<label class="journey-field">${l}<input type="number" min="0" max="${k==='investment'||k==='recurring'?1e12:100}" step="any" data-hello="${k}" value="${a[k]}"></label>`).join('')}</div></details>`}
function credentialEditor(){if(s.t!==1)return '';const c=s.credentialCosts||{people:0,badge:0,token:0,combined:0,replacement:0};return `<details class="inline-editor"><summary>Credential unit economics</summary><p class="small">Enter additional credential costs not already included in migration or annual costs. Replacement fraction is annual; initial combined issuance is added once.</p><div class="journey-fields">${Object.entries({people:'Employees',badge:'Physical badge (USD)',token:'Separate IT token (USD)',combined:'Combined credential (USD)',replacement:'Annual replacement fraction (0–1)'}).map(([k,l])=>`<label class="journey-field">${l}<input type="number" min="0" max="${k==='replacement'?1:1e8}" step="any" data-credential="${k}" value="${c[k]}"></label>`).join('')}</div></details>`}
function compactContext(){const c=context(s);return `<div class="panel compact-context"><div class="eyebrow">Investment context</div><strong>${esc(c.type==='standalone'?'Standalone initiative':c.programme||'Wider programme')}</strong><p class="small">${esc(c.owner)} · ${esc(c.type)}</p>${link(1,'Refine investment context')}</div>`}
function programmeSummary(){const c=context(s),d=financial(s).decision;return `<div class="programme-summary"><h3>Programme implications</h3>${c.type!=='standalone'&&c.budget>0?`<div class="budget-equation"><div><small>Original budget</small><strong>${money(c.budget)}</strong></div><b>+</b><div><small>Net additional budget</small><strong>${money(d.incremental)}</strong></div><b>=</b><div><small>Revised budget</small><strong>${money(d.revised)}</strong></div></div>`:''}<p class="small">${c.type!=='standalone'?'Launch impact: '+d.delay+' months. ':''}Cost of inaction equals baseline less planned expenditure. Unquantified security losses excluded.</p>${link(1,'Review financial assumptions')}</div>`}
function investmentView(editable=false){const c=context(s),f=financial(s),d=f.decision, scoped=c.type!=='standalone';const field=(k,label,type='number')=>`<label class="journey-field">${label}<input data-invest="${k}" type="${type}" ${type==='number'?'min="0" max="'+(['launch','start','gate','deferral'].includes(k)?120:1e12)+'" step="1"':'maxlength="160"'} value="${esc(c[k])}"></label>`;const choose=(k,label,opts)=>`<label class="journey-field">${label}<select data-invest="${k}">${opts.map(([v,l])=>`<option value="${v}" ${c[k]===v?'selected':''}>${l}</option>`).join('')}</select></label>`;return `<section class="panel investment-context-panel"><div class="eyebrow">Investment context · illustrative until validated</div><h2>${esc(scoped?(c.programme||'Wider programme'):t().name)}</h2><p>${esc(t().name)}${c.owner?' · '+esc(c.owner):''}</p>${editable?`<details class="inline-editor"><summary>✎ Edit investment context</summary><div class="journey-fields">${choose('type','Scope',[['standalone','Standalone initiative'],['programme','Programme workstream'],['enhancement','Platform enhancement']])}${scoped?field('programme','Parent programme / platform','text')+field('owner','Business owner','text')+field('budget','Original budget (USD)')+field('allocated','Authentication budget already included (USD)')+field('launch','Original launch month')+field('start','Integration start month')+field('gate','Additional release gate months')+choose('strategy','Delivery strategy',[['parallel','Parallel integration'],['before-launch','Required before launch'],['after-launch','Subsequent release']])+field('delayCost','Estimated net cost per launch-delay month (USD)'):''}${field('deferral','Compare deferral (months)')}</div></details>`:''}<div id="investment-results">${investmentResults()}</div>${editable?credentialEditor()+helloEditor():''}${editable?`<details class="inline-editor"><summary>✎ Implementation cost breakdown</summary><label><input type="checkbox" data-invest="itemized" ${c.itemized?'checked':''}> Use itemized estimate instead of migration investment</label><div class="journey-fields">${field('product','Product / initial licence (USD)')}${field('integration','Integration (USD)')}${field('testing','Testing and deployment (USD)')}${field('contingency','Contingency (USD)')}</div><p class="small">Itemized amounts replace the migration estimate, not add to it. Selected security remediation is added once.</p></details>`:''}</section>`}
function investmentResults(){const c=context(s),f=financial(s),d=f.decision,scoped=c.type!=='standalone',max=Math.max(1,d.baseline,d.now,d.later),bar=(label,v,color)=>`<div class="decision-bar"><div><span>${label}</span><strong>${money(v)}</strong></div><i style="width:${100*v/max}%;background:${color}"></i></div>`;const metric=(l,v)=>`<div><small>${l}</small><strong>${v}</strong></div>`;const span=Math.max(1,c.launch,d.ready,d.launch);return `${scoped&&c.budget>0?`<div class="budget-equation">${metric('Original budget',money(c.budget))}<b>+</b>${metric('Net additional budget',money(d.incremental))}<b>=</b>${metric('Revised budget',money(d.revised))}</div><p class="small">Implementation ${money(d.investment)} less already allocated ${money(c.allocated)}. ${c.budget?((d.incremental/c.budget)*100).toFixed(2)+'% change.':''} Programme budget is excluded from initiative cash flows.</p>`:''}<h3>${s.finance.years}-year comparative expenditure</h3>${bar('Retain existing approach',d.baseline,'#84968b')}${bar('Proceed as planned',d.now,'#75ce97')}${bar('Defer '+c.deferral+' months',d.later,'#d1ab67')}${s.t===2?`<p>Windows Hello alternative: <strong>${alternativeEconomics(s)?money(alternativeEconomics(s).proposed):'Not assessed'}</strong> · initiative expenditure excluding programme delay and selected remediation.</p>`:''}<div class="kpis">${metric('Net cost of inaction',money(d.coi))}${metric('Additional cost of deferral',money(d.deferralCost))}${metric('Implementation investment',money(d.investment))}</div><p class="small">Cost of inaction = existing expenditure − planned expenditure. Includes entered launch-delay costs; excludes unquantified fraud and opportunity losses. Undiscounted; existing CFO NPV excludes programme delay costs.</p>${scoped?`<h3>Programme delivery</h3><div class="delivery-track"><span>Original programme · M${c.launch}</span><i style="width:${100*c.launch/span}%"></i></div><div class="delivery-track"><span>Integration · M${d.start}–${d.start+s.finance.ramp}</span><i style="margin-left:${100*d.start/span}%;width:${100*s.finance.ramp/span}%;background:#75ce97"></i></div><div class="delivery-track"><span>Revised launch · M${d.launch}</span><i style="width:${100*d.launch/span}%;background:#d1ab67"></i></div><p>Net launch delay: <strong>${d.delay} months</strong> · estimated delay cost ${money(d.delayNowCost)}</p>`:''}<div class="strategy-comparison"><div><small>Existing approach</small><strong>${esc(current())}</strong></div><span>→</span><div><small>Proposed approach</small><strong>${esc(target())}</strong></div></div><p class="small">${esc(guidance[s.t].roles[2][0])}</p>`}
function render(){const f=financial(s), gs=gaps(s), count=gapCount();let content='';if(role==='home'){content=`<div class="eyebrow">Executive decision instrument</div><h1>From the boardroom to the terminal<span class="mint">.</span></h1><p class="lead">One initiative. Five perspectives. <strong>Informed decisions.</strong></p><div class="caseband"><span>▣ &nbsp; EXECUTIVE BRIEFCASE</span><span>01 / SELECT INITIATIVE</span></div>${opportunity(f,count)}${perspectives()}`}else{content=`<div class="eyebrow">${roles[+role][0]} / ${roles[+role][3]} · ${esc(t().name)}</div><h1>${roles[+role][1]}<span class="mint">.</span></h1><p class="lead">${descriptions[+role]}</p><div class="initiative-context"><strong>${esc(t().name)}</strong> · ${esc(s.context)}<br>${esc(current())} → ${esc(target())}</div>${workspaceNav()}<div class="eyebrow">01 / Understand</div><div class="workspace">`;if(role==='1'){content+=`<section class="panel"><div class="eyebrow">${s.finance.years}-year net benefit · undiscounted</div><div id="net" class="hero-number ${f.net<0?'amber':''}">${money(f.net)}</div><div id="chartarea">${chart(f)}</div><div class="kpis" id="kpis">${kpis(f)}</div></section><section class="panel"><div class="eyebrow">Investment drivers</div><h2>What changes the outcome?</h2><div id="drivers">${drivers(f)}</div><p class="small">Linear rollout, monthly cash flows. No fraud or revenue uplift assumed.</p>${link(3,'Review security gaps')}</section>`}else if(role==='2'){content+=`<section class="panel"><div class="eyebrow">Proposed reference architecture</div><h2>${esc(target())}</h2>${t().domains.map((d,i)=>`<button class="node" data-domain="${i}"><small>${['◎','◇','⇄','▣','↻'][i]} &nbsp; 0${i+1} / DOMAIN</small><br><strong>${esc(d)}</strong> <span style="float:right">↗</span></button>${i<4?'<div class="connector">↓</div>':''}`).join('')}</section><section class="panel"><div class="eyebrow">Delivery readiness</div><div id="delivery-count" class="hero-number amber">${count}</div><h2>Design gaps to review</h2><p>Rollout assumption: ${s.finance.ramp} months. Proposed controls require implementation evidence.</p><div class="rowline">Recovery <strong>${esc(s.recovery)}</strong></div><div class="rowline">Enrolment verification <strong>${s.proofing?'Specified':'Missing'}</strong></div><div class="rowline">${s.t===1?'Trust separation':'Session protection'} <strong>${(s.t===1?s.separation:s.session)?'Specified':'Missing'}</strong></div>${link(3,'Challenge this design')}</section>`}else if(role==='3'){content+=`<section class="panel"><div class="eyebrow">Identified gaps in example design</div><div class="hero-number amber">${count}</div>${gs.map(g=>`<div class="gap ${g.missing?'':'ok'}"><small>${g.id} · ${g.missing?'Design requirement missing':'Control proposed · evidence required'}</small><h3>${g.title}</h3><p>${g.missing?g.why:"Requirement specified; implementation effectiveness remains unverified."}</p><p class="small">${g.action}</p>${inlineEditor('Control requirement',securityField(g.id))}<div class="funding-box"><label class="funding-choice"><input type="checkbox" data-gap="${g.id}" ${g.selected?'checked':''}><span><strong>Include in investment request</strong><small data-funding-status="${g.id}">${g.selected?'Included in budget':'Not included in budget'}</small></span></label><label class="funding-cost">Estimated implementation cost ${currencyField('investment',`<input aria-label="Estimated implementation cost in USD" type="number" min="0" max="1000000000000" data-cost="${g.id}" value="${g.amount}">`)}</label><small>Change the estimate, then select inclusion to request funding.</small></div></div>`).join('')}</section><section class="panel"><div class="eyebrow">Security investment request</div><div id="extra" class="hero-number">${money(f.extra)}</div><p>Selected remediation estimates are added once to the migration investment.</p><div class="rowline">CIO <span>Validate scope</span></div><div class="rowline">CFO <span>Evaluate funding</span></div><div class="rowline">CRO <span>Assess residual risk</span></div><div id="impact-summary">${impactSummary()}</div>${link(1,'Revisit investment case')}<p class="small">No live vulnerability scanning. Costs are illustrative, not quotations.</p></section>`}else if(role==='4'){content+=riskView(gs)}else{content+=`<section class="panel"><div class="eyebrow">${role==='0'?'Strategic decision':'Residual exposure'}</div><h2>${esc(narrative(s).headline)}</h2><p>${esc(narrative(s).problem)}</p><p>${esc(narrative(s).transformation)}</p><div class="hero-number ${role==='4'?'amber':''}">${role==='0'?money(f.net):count}</div><p>${role==='0'?'Illustrative net benefit over '+s.finance.years+' years':'Unresolved example design gaps; risk is not quantified'}</p>${gs.map(g=>`<div class="rowline"><span>${g.title}</span><small class="${g.missing?'amber':''}">${g.missing?'Open design gap':'Evidence required'}</small></div>`).join('')}</section><section class="panel"><div class="eyebrow">Accountable decision</div><h2>${esc(s.decision)}</h2><p>Risk owner: ${esc(s.owner||'Not assigned')}</p><p>${count} open design gaps · ${riskRows(s,gs).filter(v=>v.status==='Not assessed').length} unassessed risks. ${s.owner?'':'Accountable owner not assigned.'} Review these before recommending a decision. Formal approval remains outside this workspace.</p>${link(2,'Review architecture')} ${link(3,'Review security findings')} ${link(4,'Assess risk & assign owner')}</section>`}if(role!=='3')content=content.replace('</section>',`${assumptionSummary()}</section>`);content+='</div>';if(role==='1'||role==='2')content+=investmentView(role==='1');if(role==='2')content+=roadmap() }const g=guidance[s.t], perspective=role==='home'?lens:+role;if(role!=='home')content+=`<details class="panel refinement-panel guidance-panel"><summary><span class="eyebrow">Strategic considerations · ${roles[perspective][0]}</span><span>${["Strategic priorities","Investment drivers","Architecture decisions","Security validation","Risk governance"][perspective]}</span></summary><div class="refinement-body"><div class="priority-grid">${perspective===1?investmentCards():g.roles[perspective].map((v,i)=>`<div class="priority-item"><span class="step-num">0${i+1}</span><p>${esc(v)}</p></div>`).join('')}</div><div class="decision-callout"><div class="eyebrow">Decision to prepare</div>${esc(g.decisions[perspective])}</div><p class="small">Planning guidance · validate against organisational evidence.</p></div></details>`+conclusion();app.innerHTML=content+(role==='home'?deliver():'')+`${role==='home'?`<section class="project-menu"><h2>Project tools</h2><div class="project-toolbar">${action('import','<svg aria-hidden="true" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"><path d="M3 7V5h6l2 2h10v3M3 7v13h15l3-10H7l-4 10"/></svg><span>Open</span>')}${action('portable','<svg aria-hidden="true" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"><path d="M4 3h13l3 3v15H4zM8 3v6h8V3M8 21v-8h8v8"/></svg><span>Save</span>')}${action('studio-open','<svg aria-hidden="true" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"><path d="M13 4h7v7M20 4l-9 9M10 5H4v15h15v-6"/></svg><span>Export / preview</span>')}${action('inspect','<svg aria-hidden="true" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"><path d="M5 3h10l4 4v14H5zM14 3v5h5M8 14l3 3 5-6"/></svg><span>Evidence</span>')}${action('clear-local','Clear local project')}<a href="/briefcase/project-reference.html" target="_blank" rel="noopener">Project reference ↗</a></div></section>`:''}<div id="local-save-status" class="statusline" role="status">${esc(storageNotice||'Changes are saved on this browser.')}</div><div class="statusline" role="status">${esc(message)}</div><div class="foot">Illustrative planning workspace · Project saved locally in this browser · No project upload. Export JSON for a portable backup. <a href="/">Toolbox and writing</a></div>`}
function kpis(f){return `<div><small>NPV</small><strong>${money(f.npv)}</strong></div><div><small>Payback</small><strong>${f.payback===null?'Not reached':f.payback.toFixed(1)+' mo'}</strong></div><div><small>Annual steady savings</small><strong>${money(f.steady)}</strong></div>`}function drivers(f){return `<div class="rowline">Baseline annual cost <strong>${money(f.base)}</strong></div><div class="rowline">Migration investment <strong>${money(financial(s).decision.investment-financial(s).extra)}</strong></div><div class="rowline">Security remediation <strong>${money(f.extra)}</strong></div><div class="rowline">Proposed total cost <strong>${money(f.proposed)}</strong></div>`}
function updateFinance(){const f=financial(s);if($('investment-results'))$('investment-results').innerHTML=investmentResults();if($('net')){$('net').textContent=money(f.net);$('net').classList.toggle('amber',f.net<0);$('chartarea').innerHTML=chart(f);$('kpis').innerHTML=kpis(f);$('drivers').innerHTML=drivers(f)}if($('extra'))$('extra').textContent=money(f.extra);if($('live'))$('live').textContent=money(f.net);if($('delivery-count'))$('delivery-count').textContent=gapCount();if($('timeline'))$('timeline').innerHTML=timeline();if($('impact-summary'))$('impact-summary').innerHTML=impactSummary();if($('risk-top'))$('risk-top').innerHTML=riskSummary();if($('risk-summary'))$('risk-summary').innerHTML=riskSummary();if(document.querySelector('.workspace-nav')&&role!=='home')document.querySelector('.workspace-nav').outerHTML=workspaceNav();if($('review-state'))$('review-state').textContent=reviewStatus(+role)+' · Working review, not formal approval.'}
const select=(k,label,values)=>`<div class="control"><label for="${k}">${label}</label><select id="${k}" data-state="${k}">${values.map(v=>`<option ${s[k]===v?'selected':''}>${esc(v)}</option>`).join('')}</select></div>`;const check=(k,label)=>`<div class="control"><label><input type="checkbox" data-state="${k}" ${s[k]?'checked':''}> ${label}</label></div>`;
function modify(){const decision=()=>select('decision','Working recommendation',['Pending review','Recommend funding','Recommend deferral','Escalate for review']);const owner=()=>`<div class="control"><label>Accountable risk owner<input data-state="owner" value="${esc(s.owner)}"></label></div>`;const finance=()=>`<div class="journey-fields">${fields.map(v=>finInput(v[0])).join('')}</div>`;const security=()=>select('recovery','Recovery mechanism',['SMS only','Alternative registered credential','Assisted re-proofing'])+check('proofing','Specify enrolment identity verification')+check(s.t===1?'separation':'session',s.t===1?'Specify independent trust domains':'Specify session protection');let html=`<h2>${role==='home'?'Initiative assumptions':roles[+role][0]+' · Refine assumptions'}</h2><p class="small">Changes apply to shared initiative data. Proposed controls require validation.</p>`;if(role==='home')html+=`<details open><summary>Strategy and ownership</summary>${decision()}${owner()}</details><details><summary>Financial assumptions · USD</summary>${finance()}</details><details><summary>Architecture and controls</summary>${controls()}</details><details><summary>Risk assessment</summary>${riskFields()}</details>`;else if(role==='0')html+=finInput('ramp')+finInput('investment');else if(role==='1')html+=finance();else if(role==='2')html+=controls()+finInput('ramp');else if(role==='3')html+=security();else html+=riskFields();open(html)}
function open(html){work.classList.toggle("referral-dialog",html.includes('id="referral-reason"'));work.classList.toggle("initiative-dialog",html.includes('class="initiative-confirm"'));body.innerHTML=html;if(!work.open){work.showModal();work.scrollTop=0}}
function brief(){const f=financial(s);return `${role==='home'?'Executive':roles[+role][0]} decision brief\n${t().name} · ${s.context}\nCurrent: ${current()}\nProposed: ${target()}\nOpportunity: ${narrative(s).headline}\n${narrative(s).problem}\n${narrative(s).transformation}\n\nDecision considerations:\n${guidance[s.t].roles.map((v,i)=>roles[i][0]+': '+v.join(' ')).join('\n')}\n\nDelivery: ${milestones(s.finance.ramp).map(v=>v.label+' M'+v.month).join(' / ')}\n${guidance[s.t].stages.join(' / ')}\n\n${s.finance.years}-year net benefit: ${money(f.net)}\nNPV: ${money(f.npv)}\nSelected remediation: ${money(f.extra)}\n\n${gaps(s).map(g=>`${g.id} ${g.title}: ${g.missing?'Design gap':'Control proposed; validate'}\n${g.action}${g.selected?' · '+money(g.amount):''}`).join('\n')}\n\nCIO: validate remediation scope and delivery.\nCFO: validate costs and funding.\nCISO: independently validate controls.\nCRO: assess residual risk.\nRisk owner: ${s.owner||'Unassigned'}\nProposed decision: ${s.decision}\nReview status: ${roles.map((r,i)=>r[0]+': '+status(s,i)).join(' · ')}\nRollout: ${s.finance.ramp} months\nRisk appetite: ${s.risk?.appetite||'Unassessed'}\n${riskRows(s,gaps(s)).map(v=>`${v.id}: ${v.inherent} → ${v.residual}; ${v.treatment}; ${v.status}; owner: ${v.owner||'Unassigned'}; evidence: ${v.evidence||'None'}; rationale: ${v.rationale||'None'}`).join('\n')}\n\nIllustrative assumptions; not verified findings or approved funding.`}
function download(name,data,type){const u=URL.createObjectURL(new Blob([data],{type}));const a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}
function inspect(){open(`<h2>Evidence &amp; methodology</h2><p class="evidence-intro">Understand the basis of your business case.</p><section class="evidence-block"><h3>Assessment basis</h3><p>Design gaps reflect missing requirements in the selected scenario. Proposed controls require validation.</p></section><section class="evidence-block"><h3>Standards &amp; methodology</h3><p>Reference points: <a href="https://pages.nist.gov/800-63-4/">NIST SP 800-63-4</a> (human digital identity), <a href="https://www.w3.org/TR/webauthn-2/">WebAuthn</a>, <a href="https://attack.mitre.org/">MITRE ATT&CK</a>. No compliance determination.</p></section><section class="evidence-block"><h3>Technical validation tools</h3><p><a href="/fido-mds-explorer/">FIDO metadata</a> · <a href="/security-key-lab/">Security key interoperability</a> · <a href="/toolbox/jwt-workbench/">Federation and tokens</a></p><p>These instruments support investigation, not production assurance.</p></section><details class="evidence-block"><summary>Financial assumptions &amp; calculation method</summary><p>Editable planning inputs; no external benchmarks.</p><p>Monthly baseline = billed events × unit cost + support cases × cost + annual fixed / 12. Savings ramp linearly using month midpoint. Incremental operating costs start in month one. Migration and selected remediation are paid at month zero. NPV discounts monthly net flows using effective annual rate.</p><pre class="brief">${esc(JSON.stringify(s.finance,null,2))}</pre></details>`)}
document.addEventListener('click',e=>{const a=e.target.closest('[data-go],[data-home],[data-template],[data-lens],[data-action],[data-domain]');if(!a)return;if(a.hasAttribute('data-go')||a.hasAttribute('data-home')){try{handoff()}catch{e.preventDefault();message='Tab storage unavailable. Save and open the project instead.';render()}return}if(a.dataset.template!==undefined){if(+a.dataset.template===s.t)return;const next=Number(a.dataset.template);open(`<section class="initiative-confirm"><h2>Switch to ${esc(templates[next].name)}?</h2><p class="switch-warning">Export JSON before replacing your current initiative.</p><div class="referral-actions"><button type="button" data-action="cancel-switch" autofocus>Cancel</button><button type="button" class="primary" data-action="confirm-switch" data-next="${next}">Switch initiative</button></div></section>`);return}if(a.dataset.lens!==undefined){lens=+a.dataset.lens;render();return}if(a.dataset.domain!==undefined){const i=+a.dataset.domain;open(`<h2>${esc(t().domains[i])}</h2><p>${gaps(s).filter(g=>g.domain===i).map(g=>esc(g.action)).join(' ')||'Validate integration, access policy and operational ownership.'} ${esc(guidance[s.t].domains[i])}</p><p>Proposed architecture; collect implementation evidence before approval.</p>${link(3,'Review security challenges')}`);return}if(/^template[0-2]$/.test(a.dataset.action)){template=+a.dataset.action.slice(-1);page=0;render();if(work.open)showStudio();return}if(/^slide[0-8]$/.test(a.dataset.action)){page=+a.dataset.action.slice(-1);render();if(work.open)showStudio();return}switch(a.dataset.action){case 'cancel-switch':work.close();break;case 'confirm-switch':{const next=Number(a.dataset.next);if(!Number.isInteger(next)||next<0||next>=templates.length||next===s.t)break;s=fresh(next);saveLocal();work.close();render();break}case 'refer':{const to=Number($('referral-target').value);open(`<section class="referral-form"><h2>Refer to ${roles[to][0]}</h2><p class="small">Request a review of the current decision within this project. No message is sent.</p><label for="referral-reason">Reason for referral</label><textarea id="referral-reason" maxlength="2000" rows="4" placeholder="What needs reconsideration, and why?" required></textarea><div class="referral-actions"><button data-action="cancel-referral" type="button">Cancel</button><button data-action="confirm-referral" data-recipient="${to}" class="primary">Save & refer to ${roles[to][0]} →</button></div></section>`);break}case 'cancel-referral':work.close();break;case 'confirm-referral':{const reason=$('referral-reason');if(!reason.value.trim()){reason.setCustomValidity('Enter a reason for referral.');reason.reportValidity();reason.setCustomValidity('');break}const to=Number(a.dataset.recipient);try{const next=JSON.parse(JSON.stringify(s));refer(next,+role,to,reason.value);s=next;handoff();location.href='/briefcase/'+roles[to][2]+'/'}catch(err){message=err.message;work.close();render()}break}case 'commit':{commit(s,+role);const next=+role+1;try{handoff();location.href=next<5?'/briefcase/'+roles[next][2]+'/':'/briefcase/#decision-brief'}catch{message='Save project to preserve your review.';render()}break}case 'clear-local':{if(!confirm('Clear the saved project and reset this workspace? Export JSON first if you need a backup.'))break;try{clear(localStorage);sessionStorage.removeItem('briefcase-handoff');s=fresh();storageNotice='Local project cleared';message='';render()}catch{storageNotice='Could not clear browser storage.';render()}break}case 'studio-open':saveLocal();studioView='slides';showStudio();break;case 'view-slides':case 'view-text':case 'view-raw':case 'view-api':studioView=a.dataset.action.slice(5);showStudio();break;case 'theme':light=light==='dark'?'light':'dark';render();showStudio();break;case 'prev':page--;showStudio();break;case 'next':page++;showStudio();break;case 'pptx':ppt();break;case 'pdf':{const w=window.open('','_blank');if(!w){$('export-status').textContent='Popup blocked. Download HTML and print externally.';break}w.opener=null;w.document.write(printHTML(deck(s,template,light)));w.document.close();w.print();break}case 'save-opportunity':{const d=a.closest('details');const v=Object.fromEntries([...d.querySelectorAll('[data-opportunity]')].map(e=>[e.dataset.opportunity,e.value.trim()]));try{validateOpportunity(v);s.opportunity=v;saveLocal();render()}catch(err){message=err.message;render()}break}case 'apply-inline':{const d=a.closest('details');const invalid=d?.querySelector(':invalid');if(invalid){invalid.reportValidity();break}saveLocal();render();break}case 'modify':modify();break;case 'inspect':inspect();break;case 'act':open(`<h2>Decision brief</h2><div class="brief">${esc(brief())}</div><div class="actions">${action('print','Print / PDF')}${action('text','Download brief')}${action('deck','Download presentation HTML')}${action('model','Download presentation model')}</div>`);break;case 'portable':download('briefcase-project.json',JSON.stringify(pack(s),null,2),'application/json');break;case 'deck':download('executive-presentation.html',printHTML(deck(s,template,light)),'text/html');break;case 'model':download('presentation.json',JSON.stringify(deck(s,template,light),null,2),'application/json');break;case 'print':window.print();break;case 'text':download('decision-brief.txt',brief(),'text/plain');break;case 'export':download('initiative.identity.json',JSON.stringify(s,null,2),'application/json');break;case 'import':{const input=document.createElement('input');input.type='file';input.accept='.json';input.onchange=async()=>{try{if(input.files[0].size>1000000)throw Error('File too large');s=unpack(JSON.parse(await input.files[0].text()));message='Project opened.';saveLocal();render()}catch(err){message='Import rejected: '+err.message;render()}};input.click();break}}});
document.addEventListener('input',e=>{const a=e.target;if(a.dataset.appetite){s.risk??=emptyRisk();s.risk.appetite=a.value;updateFinance()}else if(a.dataset.risk){s.risk??=emptyRisk();s.risk.records[a.dataset.risk]??=emptyRecord();s.risk.records[a.dataset.risk][a.dataset.key]=a.value;updateFinance()}else if(a.dataset.fin){const v=a.valueAsNumber;if(!Number.isFinite(v)||!a.checkValidity())return;const old=s.finance[a.dataset.fin];s.finance[a.dataset.fin]=v;try{financial(s)}catch{s.finance[a.dataset.fin]=old;return}document.querySelectorAll(`[data-fin="${a.dataset.fin}"]`).forEach(b=>{if(b!==a)b.value=v});updateFinance()}else if(a.dataset.cost){if(!Number.isFinite(a.valueAsNumber)||!a.checkValidity())return;const old=s.costs[a.dataset.cost];s.costs[a.dataset.cost]=a.valueAsNumber;try{updateFinance()}catch{if(old===undefined)delete s.costs[a.dataset.cost];else s.costs[a.dataset.cost]=old}}else if(a.dataset.gap){s.selected[a.dataset.gap]=a.checked;const label=document.querySelector(`[data-funding-status="${a.dataset.gap}"]`);if(label)label.textContent=a.checked?'Included in budget':'Not included in budget';updateFinance()}else if(a.dataset.state){if(a.dataset.state==='currency')return;s[a.dataset.state]=a.type==='checkbox'?a.checked:a.value;updateFinance()}});$('closework').onclick=()=>work.close();work.addEventListener('close',render);render();if(role==='home'&&location.hash==='#decision-brief')requestAnimationFrame(()=>$('decision-brief')?.scrollIntoView());

$("closeworktop").addEventListener("click",()=>work.close());

document.addEventListener('change',e=>{if(role==='home' && e.target.dataset.fin && !work.open){const opened=[...document.querySelectorAll('.dossier-bottom details')].map(x=>x.open);render();document.querySelectorAll('.dossier-bottom details').forEach((x,i)=>x.open=!!opened[i]);}});

document.addEventListener("change",e=>{if(e.target.id==="referral-target")document.querySelector('[data-action="refer"]').textContent="Refer to "+roles[Number(e.target.value)][0]+" ↗"});

// Save accepted model changes after the existing input handler runs.
document.addEventListener('input',e=>{if(e.target.matches('[data-appetite],[data-risk],[data-fin],[data-cost],[data-gap],[data-state]'))saveLocal()});

document.addEventListener('change',e=>{const a=e.target,k=a.dataset.invest;if(!k)return;const c={...context(s)},v=a.type==='checkbox'?a.checked:a.type==='number'?a.valueAsNumber:a.value;if(!a.checkValidity())return;c[k]=v;try{validateContext(c);s.investmentContext=c;saveLocal();const idx=[...document.querySelectorAll(".investment-context-panel details")].indexOf(a.closest("details"));render();const detail=document.querySelectorAll(".investment-context-panel details")[idx];if(detail)detail.open=true;}catch(err){a.setCustomValidity(err.message);a.reportValidity();a.setCustomValidity('')}});

document.addEventListener('change',e=>{const a=e.target,k=a.dataset.credential;if(!k||!a.checkValidity()||!Number.isFinite(a.valueAsNumber))return;s.credentialCosts={people:0,badge:0,token:0,combined:0,replacement:0,...s.credentialCosts,[k]:a.valueAsNumber};saveLocal();updateFinance()});

document.addEventListener('change',e=>{const a=e.target,k=a.dataset.hello;if(!k||!a.checkValidity()||!Number.isFinite(a.valueAsNumber))return;s.helloFinance={investment:0,recurring:0,displace:0,supportReduction:0,...s.helloFinance,[k]:a.valueAsNumber};saveLocal();updateFinance()});
